import axios from 'axios';

const TMDB_API_KEY = '8c247ea0b4b56ed2ff7d41c9a833aa77';
const TMDB_API_URL = 'https://api.themoviedb.org/3';

export const tmdbService = {
  // Get content details (movie or TV show)
  getContentDetails: async (id, type = 'movie') => {
    try {
      const response = await axios.get(`${TMDB_API_URL}/${type}/${id}`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'en-US',
          append_to_response: 'videos,release_dates,credits,similar'
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching content details:', error);
      throw error;
    }
  },

  // Get similar content
  getSimilarContent: async (id, type = 'movie') => {
    try {
      const response = await axios.get(`${TMDB_API_URL}/${type}/${id}/similar`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'en-US',
          page: 1
        }
      });
      return response.data.results;
    } catch (error) {
      console.error('Error fetching similar content:', error);
      throw error;
    }
  },

  // Get content recommendations
  getRecommendations: async (id, type = 'movie') => {
    try {
      const response = await axios.get(`${TMDB_API_URL}/${type}/${id}/recommendations`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'en-US',
          page: 1
        }
      });
      return response.data.results;
    } catch (error) {
      console.error('Error fetching recommendations:', error);
      throw error;
    }
  },

  // Search content
  searchContent: async (query, type = 'multi') => {
    try {
      const response = await axios.get(`${TMDB_API_URL}/search/${type}`, {
        params: {
          api_key: TMDB_API_KEY,
          query,
          language: 'en-US',
          include_adult: false
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error searching content:', error);
      throw error;
    }
  }
};
